#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "state_need_task.hpp"
#include "resident/model/commitment_ref_codec.hpp"
#include "task_dynamic_codec.hpp"
namespace hanmo::resident {
namespace {
using namespace dynamic_codec;
template<class A>Status source(A&a,SourceRef&v){a.field("domain",v.domain);a.field("kind",v.kind);return a.field("id",v.id);}
template<class A>Status need(A&a,StateNeedRef&v){a.field("need_id",v.need_id);return a.field("episode",v.episode);}
template<class A>Status goal(A&a,StateGoalRef&v){Integer kind=v.index();a.field("kind",kind);if(kind<0||kind>1)return a.reject("UnknownStateGoal");if(a.reading()){if(kind==0)v=CareCoverageGoal{};else v=MedicalResolutionGoal{};}if(auto*p=std::get_if<CareCoverageGoal>(&v)){a.field("care_requirement_id",p->care_requirement_id);return a.field("subject_actor_id",p->subject_actor_id);}auto&p=std::get<MedicalResolutionGoal>(v);a.field("medical_need_id",p.medical_need_id);return a.field("patient_actor_id",p.patient_actor_id);}
template<class A>Status satisfaction(A&a,StateSatisfactionRef&v){Integer kind=v.index();a.field("kind",kind);if(kind<0||kind>1)return a.reject("UnknownStateSatisfaction");if(a.reading()){if(kind==0)v=CareGoalSatisfaction{};else v=MedicalGoalSatisfaction{};}return std::visit([&](auto&x){a.object("source",[&](auto&c){return source(c,x.source);});return a.field("source_schema",x.source_schema);},v);}
template<class A>Status gate(A&a,StateNeedDeadline&v){a.field("tick",v.tick);return a.field("inclusive",v.inclusive);}
template<class A>Status objective(A&a,StateNeedObjectiveBinding&v){a.object("need_ref",[&](auto&c){return need(c,v.need_ref);});a.object("goal_ref",[&](auto&c){return goal(c,v.goal_ref);});a.field("goal_source_episode",v.goal_source_episode);enumeration(a,"criterion",v.criterion,2);a.field("required_actor_role",v.required_actor_role);a.field("claim_id",v.claim_id);return a.field("disclosure_policy_ref",v.disclosure_policy_ref);}
template<class A>Status money(A&a,StateTaskMoneyTerms&v){a.object("original_terms_ref",[&](auto&c){return source(c,v.original_terms_ref);});a.object("terms_revision",[&](auto&c){return commitment_codec::terms(c,v.terms_revision);});a.field("funding_wallet_id",v.funding_wallet_id);a.field("reward_wallet_id",v.reward_wallet_id);a.field("payee_wallet_id",v.payee_wallet_id);a.object("issuer",[&](auto&c){return owner(c,v.issuer);});a.field("maximum_service_fee",v.maximum_service_fee);return a.field("success_reward",v.success_reward);}
template<class A>Status refs(A&a,const StableId&key,std::vector<SourceRef>&v){return a.sequence(key,v,[](auto&c,auto&x){return source(c,x);});}
template<class A>Status fields(A&a,StateNeedTaskState&s){
 table(a,"offers",s.offers,[](auto&c,auto&v){c.object("offer_ref",[&](auto&x){return offer_ref(x,v.offer_ref);});c.object("need_ref",[&](auto&x){return need(x,v.need_ref);});c.field("goal_summary",v.goal_summary);c.field("terms_ref",v.terms_ref);c.field("claim_window",v.claim_window);c.object("completion_gate",[&](auto&x){return gate(x,v.completion_gate);});c.object("fee_reward_terms",[&](auto&x){return money(x,v.fee_reward_terms);});c.field("cancel_policy",v.cancel_policy);c.object("original_disclosure_ref",[&](auto&x){return source(x,v.original_disclosure_ref);});c.object("report_recipient",[&](auto&x){return subject(x,v.report_recipient);});c.field("report_required",v.report_required);return c.object("objective",[&](auto&x){return objective(x,v.objective);});});
 table(a,"contracts",s.contracts,[](auto&c,auto&v){c.field("id",v.id);c.field("task_id",v.task_id);c.field("offer_id",v.offer_id);c.field("acceptance_id",v.acceptance_id);c.field("escrow_wallet_id",v.escrow_wallet_id);c.object("assignee",[&](auto&x){return subject(x,v.assignee);});c.field("executor_actor_id",v.executor_actor_id);c.object("objective",[&](auto&x){return objective(x,v.objective);});c.object("money",[&](auto&x){return money(x,v.money);});c.object("completion_gate",[&](auto&x){return gate(x,v.completion_gate);});c.field("cancel_policy",v.cancel_policy);c.object("report_recipient",[&](auto&x){return subject(x,v.report_recipient);});c.field("report_required",v.report_required);c.object("accepted_at",[&](auto&x){return exact_moment(x,v.accepted_at);});c.field("claim_until_tick",v.claim_until_tick);c.field("accepted_goal_revision",v.accepted_goal_revision);enumeration(c,"phase",v.phase,2);c.optional("closing_cause",v.closing_cause,[](auto&x,auto&value){return enumeration(x,"value",value,6);});c.optional("contribution_id",v.contribution_id,[](auto&x,auto&value){return x.field("value",value);});c.optional("report_receipt",v.report_receipt,[](auto&x,auto&value){return source(x,value);});c.optional("settlement_source",v.settlement_source,[](auto&x,auto&value){return source(x,value);});return c.optional("closing_source",v.closing_source,[](auto&x,auto&value){return source(x,value);});});
 table(a,"predicate_contributions",s.predicate_contributions,[](auto&c,auto&v){c.field("id",v.id);c.field("contract_id",v.contract_id);c.field("claim_id",v.claim_id);c.field("need_id",v.need_id);c.field("episode",v.episode);enumeration(c,"criterion",v.criterion,2);c.object("satisfaction_ref",[&](auto&x){return satisfaction(x,v.satisfaction_ref);});c.object("actual_contribution_ref",[&](auto&x){return source(x,v.actual_contribution_ref);});return c.object("applied_result_ref",[&](auto&x){return source(x,v.applied_result_ref);});});
 table(a,"settlements",s.settlements,[](auto&c,auto&v){c.field("id",v.id);c.field("contract_id",v.contract_id);enumeration(c,"cause",v.cause,6);refs(c,"service_charge_sources",v.service_charge_sources);c.field("paid_service_fee",v.paid_service_fee);c.field("paid_success_reward",v.paid_success_reward);c.field("refunded_service_fee",v.refunded_service_fee);c.field("refunded_reward",v.refunded_reward);return c.object("settled_at",[&](auto&x){return exact_moment(x,v.settled_at);});});
 table(a,"closures",s.closures,[](auto&c,auto&v){c.field("id",v.id);c.field("contract_id",v.contract_id);enumeration(c,"cause",v.cause,6);c.optional("actual_service_stop_ref",v.actual_service_stop_ref,[](auto&x,auto&value){return source(x,value);});return c.object("closed_at",[&](auto&x){return exact_moment(x,v.closed_at);});});return a.status();
}
}
Outcome<StateNeedTaskState> decode_state_need_tasks(const BoundaryValue&value){StateNeedTaskState s;JsonArchive a(value);auto r=fields(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<StateNeedTaskState>{true,std::move(s),{}}:Outcome<StateNeedTaskState>{false,{},r.error};}
Status emit_state_need_tasks_projection(ProjectionWriter&sink,std::string_view key,const StateNeedTaskState&value){return dynamic_projection::emit(sink,key,value,[](auto&a,auto&v){return fields(a,v);});}
Outcome<BoundaryValue> encode_state_need_tasks(const StateNeedTaskState&value){return dynamic_projection::encode(value,[](auto&a,auto&v){return fields(a,v);});}
Status visit_state_need_tasks_checkpoint(CodecVisitor&a,StateNeedTaskState&s){return fields(a,s);}
}
